def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def get_int(key, default=0):
        try:
            return int(observation.get(key, default))
        except Exception:
            return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    env = observation.get("environment_name", "resource_collection")
    role = observation.get("self_role", "pursuer")

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        w = get_int("grid_width", 0)
        h = get_int("grid_height", 0)
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        best = None
        best_score = None
        for t in corners:
            score = dist((sx, sy), t) - dist((ox, oy), t)
            if best is None or score > best_score:
                best = t
                best_score = score
        if best is None:
            return [0, 0]
        return step_toward((sx, sy), best)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = None
        best_score = None
        if targets:
            for item in targets:
                t = pos(item, None)
                if t is None:
                    continue
                score = dist((sx, sy), t)
                if best is None or score < best_score:
                    best = t
                    best_score = score
            if best is not None:
                return step_toward((sx, sy), best)
        w = get_int("grid_width", 0)
        h = get_int("grid_height", 0)
        center = (w // 2, h // 2)
        return step_toward((sx, sy), center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = None
        best_score = None
        for item in resources:
            t = pos(item, None)
            if t is None:
                continue
            score = dist((sx, sy), t)
            if best is None or score < best_score:
                best = t
                best_score = score
        if best is not None:
            return step_toward((sx, sy), best)

    if ox != sx or oy != sy:
        return step_toward((sx, sy), (ox, oy))

    return [0, 0]

